CREATE TABLE customers (
  customer_id   NUMBER        PRIMARY KEY,
  customer_name VARCHAR2(50)  NOT NULL
);

CREATE TABLE orders (
  order_id     NUMBER  PRIMARY KEY,
  customer_id  NUMBER,          -- nullable: guest orders
  amount       NUMBER(10,2)
);

INSERT INTO customers VALUES (1, 'Asha');
INSERT INTO customers VALUES (2, 'Ravi');
INSERT INTO customers VALUES (3, 'Meena');
INSERT INTO customers VALUES (4, 'John');

INSERT INTO orders VALUES (101, 1, 1200);
INSERT INTO orders VALUES (102, 1,  450);
INSERT INTO orders VALUES (103, 3,  980);
COMMIT;

INSERT INTO orders VALUES (105, 9, 750);  -- customer 9 does not exist
COMMIT;

SELECT order_id, customer_id
  FROM orders
 WHERE customer_id NOT IN (SELECT customer_id FROM customers)
 ORDER BY order_id;

EXPLAIN PLAN FOR
SELECT customer_id, customer_name
  FROM customers
 WHERE customer_id NOT IN (SELECT customer_id FROM orders);

